Для синхронизации используется <code>std::mutex</code>:<br><pre><code>#include &lt;mutex&gt;

std::mutex mut;

void myfun(std::string str) {
    for (int i = 0; i &lt; 10; i++) {
        mut.lock();                        // Блокируем
        std::cout &lt;&lt; std::endl &lt;&lt; str;
        mut.unlock();                      // Снимаем блокировку
    }
}</code></pre>
